import { Box, Container, Stack, Typography } from "@mui/material";
import BlocksText from "../components/BlocksText";
import { mediaUrl } from "../services/api";
import type { HomeFeature } from "../types/home";

const NAVY = "#17224d";
const BLUE = "#759ae1";
const BODY = "#5a6473";
const DASH = "1.5px dashed rgba(106, 106, 106, 0.42)";

type FeaturesProps = {
  items?: HomeFeature[];
};

function featureFrame(index: number) {
  const textLeft = index % 2 === 0;
  if (textLeft) {
    if (index === 0) {
      return {
        borderRight: DASH,
        borderBottom: DASH,
        borderBottomRightRadius: "40px",
        pr: { xs: 2, sm: 3, md: 5, lg: 6, tv: 8 },
        pb: { xs: 2, sm: 2.5, md: 3, tv: 4 },
      };
    }
    return {
      borderTop: DASH,
      borderRight: DASH,
      borderTopRightRadius: "40px",
      pt: { xs: 2, sm: 2.5, md: 3, tv: 4 },
      pr: { xs: 2, sm: 3, md: 5, lg: 6, tv: 8 },
    };
  }

  if (index % 6 === 5) {
    return {
      borderBottom: DASH,
      borderLeft: DASH,
      borderBottomLeftRadius: "40px",
      pb: { xs: 2, sm: 2.5, md: 3, tv: 4 },
      pl: { xs: 2, sm: 3, md: 5, lg: 6, tv: 8 },
    };
  }

  return {
    borderTop: DASH,
    borderLeft: DASH,
    borderTopLeftRadius: "40px",
    pt: { xs: 2, sm: 2.5, md: 3, tv: 4 },
    pl: { xs: 2, sm: 3, md: 5, lg: 6, tv: 8 },
  };
}

export default function Features({ items = [] }: FeaturesProps) {
  if (!items.length) return null;

  return (
    <Box sx={{ py: { xs: 4, sm: 6, md: 8, lg: 10, tv: 12 }, backgroundColor: "#fff" }}>
      <Container
        maxWidth={false}
        sx={{ px: { xs: 2, sm: 3, md: 5, tv: 8 }, maxWidth: { xs: "100%", md: "95%", tv: 1680 } }}
      >
        <Stack spacing={{ xs: 4, sm: 6, md: 8, lg: 10, tv: 12 }}>
          {items.map((item, index) => {
            const image = mediaUrl(item.image);
            const textLeft = index % 2 === 0;
            return (
              <Stack
                key={item.id || item.title}
                direction={{ xs: "column", md: textLeft ? "row" : "row-reverse" }}
                alignItems="center"
                spacing={{ xs: 2.5, sm: 3, md: 5, lg: 6, tv: 8 }}
              >
                <Box sx={{ flex: 1, width: "100%", ...featureFrame(index) }}>
                  <Typography
                    sx={{
                      color: BLUE,
                      fontSize: { xs: 28, sm: 36, md: 46, lg: 54, tv: 64 },
                      fontWeight: 900,
                      letterSpacing: "1.08px",
                      lineHeight: 1.2,
                      mb: 0,
                    }}
                  >
                    {String(index + 1).padStart(2, "0")}
                  </Typography>
                  <Typography
                    component="h2"
                    sx={{
                      color: NAVY,
                      fontSize: { xs: 20, sm: 26, md: 32, lg: 36, tv: 42 },
                      fontWeight: 600,
                      lineHeight: 1.15,
                      letterSpacing: "0.5px",
                      mb: 1.5,
                    }}
                  >
                    {item.title}
                  </Typography>
                  <BlocksText
                    content={item.description}
                    sx={{
                      color: BODY,
                      fontSize: { xs: 14, sm: 15, md: 17, lg: 18, tv: 20 },
                      lineHeight: 1.65,
                      letterSpacing: "0.32px",
                      "& p": { mb: 0 },
                      "& strong": { fontWeight: 700, color: BODY },
                    }}
                  />
                </Box>
                {image ? (
                  <Box sx={{ flex: 1, width: "100%", textAlign: "center" }}>
                    <Box
                      component="img"
                      src={image}
                      alt={item.image?.alternativeText || item.title}
                      sx={{
                        width: "100%",
                        maxWidth: { xs: 280, sm: 360, md: 440, lg: 500, tv: 620 },
                        display: "block",
                        mx: textLeft ? { xs: "auto", md: 0 } : "auto",
                        ml: textLeft ? { md: "auto" } : { xs: "auto", md: 0 },
                      }}
                    />
                  </Box>
                ) : null}
              </Stack>
            );
          })}
        </Stack>
      </Container>
    </Box>
  );
}
